// rustorb C++ implementation of the InteropTest client, with stubs and
// skeletons generated by rustorb-idl -bc++11.
//
// Resolves the Echo object from the naming service, runs every test case
// against it and exits non-zero if any case fails.

#include <sstream>

#include "cases.h"
#include "common.h"

int main(int argc, char** argv) {
  std::vector<std::string> orb_args;
  Options opt = parse_args(argc, argv, orb_args);
  try {
    auto orb = orb_init(orb_args);
    auto poa = persistent_poa(orb, "InteropTestClient");

    auto root = root_context(orb, opt.timeout);
    CosNaming::Name name = to_name(opt.name);
    auto obj = retry("the Echo server", [&]() { return root->resolve(name); }, opt.timeout);
    auto echo = IDL::traits<InteropTest::Echo>::narrow(obj);
    if (!echo) {
      std::cout << opt.name << " is not an InteropTest::Echo" << std::endl;
      return 1;
    }
    retry("the Echo server", [&]() { return echo->_non_existent(); }, opt.timeout);

    Runner r;
    run_cases(r, echo, poa);

    if (opt.shutdown_server) echo->shutdown();

    r.summary();
    orb->destroy();
    return r.failed().empty() ? 0 : 1;
  } catch (const CORBA::Exception& e) {
    std::cerr << "CORBA exception: " << e << std::endl;
    return 1;
  }
}
